const CapacityFeature={id:"capacity",name:"Availability",icon:"event_busy",route:!1,async render(){const a=new Date;a.setHours(0,0,0,0);const t=new Date(a);t.setDate(t.getDate()+90);let e=[];try{e=await DB.getAvailabilityBlocks({from:a.toISOString(),to:t.toISOString()})}catch(a){console.error("Availability failed:",a)}return`<div class="fade-in">\n      ${App.renderTopHeader({title:"Availability",showBack:!0,backHref:"control",actions:'<button class="btn btn-primary btn-sm" data-action="CapacityFeature.openAdd"><span class="material-symbols-rounded">add</span>Block time</button>'})}\n      <div class="p-md">\n        <div class="card mb-md"><div class="fw-600">Capacity advice, not auto-booking</div><div class="fs-13 text-secondary mt-xs">Beelo warns about leave, closed hours, clashes and overloaded days. It never moves a customer visit by itself.</div></div>\n        ${e.length?e.sort((a,t)=>new Date(a.startAt)-new Date(t.startAt)).map(a=>this.card(a)).join(""):'<div class="empty-state empty-state-lg"><span class="material-symbols-rounded">event_available</span><div class="fw-600">No blocked time ahead</div><div class="fs-13">Add leave or unavailable periods so booking advice reflects the day you can deliver.</div></div>'}\n      </div></div>`},card(a){const t=a.label||("leave"===a.type?"Leave":"Unavailable");return`<article class="card mb-sm"><div class="flex justify-between gap-sm"><div><div class="fw-600">${Utils.escapeHtml(t)}</div><div class="fs-13 text-secondary">${Utils.formatDate(a.startAt,"short")} · ${Utils.formatTime(a.startAt)}–${Utils.formatTime(a.endAt)}</div></div><button class="btn btn-ghost btn-sm" aria-label="Delete ${Utils.escapeHtml(t)}" data-action="CapacityFeature.remove" data-args='${JSON.stringify([a.id])}'><span class="material-symbols-rounded">delete</span></button></div></article>`},openAdd(){const a=new Date;a.setMinutes(0,0,0);const t=new Date(a.getTime()+36e5),e=a=>`${Utils.formatDate(a,"iso")}T${Utils.formatTime(a)}`;App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>Block diary time</h3><button class="btn btn-ghost btn-sm" aria-label="Close" data-action="App.closeModal"><span class="material-symbols-rounded">close</span></button></div><div class="sheet-body">\n      <div class="form-group"><label for="capacity-type">Reason</label><select class="select" id="capacity-type"><option value="unavailable">Unavailable</option><option value="leave">Leave</option></select></div>\n      <div class="form-group"><label for="capacity-label">Label</label><input class="input" id="capacity-label" placeholder="Holiday, paperwork, personal appointment"></div>\n      <div class="form-group"><label for="capacity-start">Starts</label><input class="input" id="capacity-start" type="datetime-local" value="${e(a)}"></div>\n      <div class="form-group"><label for="capacity-end">Ends</label><input class="input" id="capacity-end" type="datetime-local" value="${e(t)}"></div>\n      <button class="btn btn-primary btn-block" id="capacity-save" data-action="CapacityFeature.save">Save blocked time</button></div>`)},async save(){if(this._saving)return;const a=document.getElementById("capacity-start")?.value,t=document.getElementById("capacity-end")?.value;if(!a||!t||new Date(a)>=new Date(t))Toast.show("End time must be after the start","warning");else{this._saving=!0;try{await DB.addAvailabilityBlock({type:document.getElementById("capacity-type")?.value,label:document.getElementById("capacity-label")?.value.trim()||"",startAt:new Date(a).toISOString(),endAt:new Date(t).toISOString()}),App.closeModal(),Toast.show("Diary time blocked","success"),App.navigate("capacity")}catch(a){Toast.show(a.message||"Could not block that time","error")}finally{this._saving=!1}}},async remove(a){confirm("Remove this blocked time?")&&(await DB.deleteAvailabilityBlock(a),Toast.show("Blocked time removed","success"),App.navigate("capacity"))}};App.registerFeature(CapacityFeature);
